Definition SNPRINTF_STACK : Z := 1360.

Definition snprintf_d_m1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (buf : word) (lo : Z) (junk : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 2) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (bv_unsigned buf, bv_unsigned buf + 22)]%Z m m'
    /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' (bv_unsigned buf) [C1 (Z_to_bv 8 45); C1 (Z_to_bv 8 49); C1 (Z_to_bv 8 0); CB 19 (skipn 3 junk)].

Definition snprintf_d_m1_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo : Z) (junk : list byte),
  F = bvmap_empty -> fc = Z_to_bv 32 0 ->
  a1 = Z_to_bv 64 22 -> a2 = Z_to_bv 64 L_STR_FMT_D -> a3 = Z_to_bv 64 18446744073709551615 ->
  bv_unsigned a0 mod 16 = 2 ->
  bv_unsigned sp mod 16 = 0 ->
  stk rsegs m lo (bv_unsigned sp) -> lo + SNPRINTF_STACK <= bv_unsigned sp -> 0x200000 <= lo ->
  bv_unsigned sp <= 0x7fffffffffff ->
  rw_cells rsegs m (bv_unsigned a0) [CB 22 junk] ->
  0x200002 <= bv_unsigned a0 -> bv_unsigned a0 + 22 <= 0x7fffffffffff ->
  (bv_unsigned a0 + 22 <= lo \/ bv_unsigned sp <= bv_unsigned a0) ->
  CanaryReads m -> mem_inv rsegs m ->
  evt rsegs (snprintf_d_m1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc a0 lo junk m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SNPRINTF) fc None m (seg_rom rsegs)).

Lemma evt_after : forall Q ms ms1, Exec.msteps rsegs ms ms1 -> evt rsegs Q ms1 -> evt rsegs Q ms.
Proof. intros Q ms ms1 H (ms' & H' & HQ). exists ms'. split; [eapply Exec.msteps_trans; eassumption | exact HQ]. Qed.
